import { describe, expect, it } from 'vitest';
import { JIRA_SPLIT_FIELDS, JIRA_STANDARD_FIELDS, jiraSearchFields } from '../src/load.ts';
import { TOIL_PROJECTS } from '../src/fixtures/toil-projects.ts';
import { loaded } from './harness.ts';

/**
 * The sample team, as Toil UI loads it: the fourth toil project, generated by
 * toil's own sampleTeam(), read through the same loader as the other three.
 * What the figures should be is docs/sample-team.md's to say; these check that
 * they arrive on the items a split reads. A spreadsheet of the same figures
 * would have been out of date by the time it was attached to the ticket.
 */

describe('sample-team', () => {
  it('comes first, described so a newcomer picks it', () => {
    expect(TOIL_PROJECTS[0]!.name).toBe('sample-team');
    expect(TOIL_PROJECTS[0]!.description).toContain('two squads, six sprints, three releases');
  });

  it('loads every work item and pull request the sample holds, with no failed call', async () => {
    const { data, calls } = await loaded('sample-team');
    expect(calls.filter((c) => !c.ok)).toEqual([]);
    expect(data.items).toHaveLength(146);
    expect(data.pullRequests).toHaveLength(16);
    expect(data.wipLimit).toBe(3);
    expect(new Set(data.people.map((p) => p.team))).toEqual(new Set(['Storefront', 'Platform']));
    expect(data.codeowners['imagile/shop']?.path).toBe('.github/CODEOWNERS');
  });

  it('carries what a split reads: versions, components, sprints, ancestors and dimensions', async () => {
    const { data } = await loaded('sample-team');
    const some = (test: (i: (typeof data.items)[number]) => boolean) => data.items.filter(test).length;
    expect(some((i) => (i.releases ?? []).length > 0)).toBeGreaterThan(50);
    expect(some((i) => (i.components ?? []).length > 0)).toBeGreaterThan(100);
    expect(some((i) => (i.sprints ?? []).length > 1)).toBe(14);
    expect(some((i) => (i.ancestors ?? []).length > 0)).toBeGreaterThan(100);
    expect(some((i) => (i.dims?.customer ?? []).length > 0)).toBe(29);
    expect(some((i) => i.resolved !== null && i.resolved !== undefined)).toBeGreaterThan(50);
  });
});

describe("the fields a Jira search asks for", () => {
  it('are, for sample-team, the standard ones, the split ones, then its own pointers and dimension, once each', () => {
    const file = TOIL_PROJECTS.find((d) => d.name === 'sample-team')!;
    expect(jiraSearchFields(file, file.jira as Record<string, unknown>)).toEqual([
      ...JIRA_STANDARD_FIELDS,
      ...JIRA_SPLIT_FIELDS,
      'customfield_10016', // estimate
      'customfield_10020', // iteration
      'customfield_10014', // epic link
      'customfield_10500', // customer, named by `fields` and by `dimensions`, asked for once
    ]);
  });

  it('are, for a toil project with only an alias, the alias too, and never a name with spaces or a label pattern', () => {
    const base = { jira: { fields: { estimate: 'Story Points', estimateLabel: 'points: {n}', estimateUnit: 'points', acceptanceCriteria: 'customfield_10500' } } };
    expect(jiraSearchFields(base, base.jira)).toEqual([...JIRA_STANDARD_FIELDS, ...JIRA_SPLIT_FIELDS, 'customfield_10500']);
  });

  it("add the classify target's field, through the section's alias when it is one", () => {
    const file = { jira: { fields: { category: 'customfield_10900' } }, classify: { targets: { jira: { field: 'category' } } } };
    expect(jiraSearchFields(file, file.jira)).toContain('customfield_10900');
    const direct = { jira: {}, classify: { targets: { jira: { field: 'customfield_10901' } } } };
    expect(jiraSearchFields(direct, direct.jira)).toContain('customfield_10901');
  });
});
